<?php

final class Reminders
{
    // Same shape, different parameter types: deliberate twins for two owners.
    protected function reminder(Contact $contact, string $uuid): Reminder
    {
        if (! Str::isUuid($uuid)) {
            throw $this->doesNotExist('That reminder does not exist.');
        }
        $reminder = $contact->reminders()->where('uuid', $uuid)->first();
        return $this->found($reminder);
    }

    protected function groupReminder(Group $group, string $uuid): Reminder
    {
        if (! Str::isUuid($uuid)) {
            throw $this->doesNotExist('That reminder does not exist.');
        }
        $reminder = $group->reminders()->where('uuid', $uuid)->first();
        return $this->found($reminder);
    }

    // Same code, different literal: the string is the difference.
    public function csvHeader(array $rows): string
    {
        $cols = array_keys($rows[0] ?? []);
        $line = implode(',', $cols);
        return $line . "\n" . 'generated by export v1';
    }

    public function tsvHeader(array $rows): string
    {
        $cols = array_keys($rows[0] ?? []);
        $line = implode("\t", $cols);
        return $line . "\n" . 'generated by export v1';
    }

    // Tiny bodies: too small to call a helper.
    public function a(): int { return 1; }
    public function b(): int { return 1; }
}
